```cpp
void OTAImageProcessorImpl::HandlePrepareDownload(intptr_t context)
{
    auto * imageProcessor = reinterpret_cast<OTAImageProcessorImpl *>(context);
    if (imageProcessor == nullptr)
    {
        ChipLogError(SoftwareUpdate, "ImageProcessor context is null");
        return;
    }
    else if (imageProcessor->mDownloader == nullptr)
    {
        ChipLogError(SoftwareUpdate, "mDownloader is null");
        return;
    }
    imageProcessor->mOTAUpdatePartition = esp_ota_get_next_update_partition(NULL);
    if (imageProcessor->mOTAUpdatePartition == NULL)
    {
        ChipLogError(SoftwareUpdate, "OTA partition not found");
        return;
    }
    esp_err_t err =
        esp_ota_begin(imageProcessor->mOTAUpdatePartition, OTA_WITH_SEQUENTIAL_WRITES, &(imageProcessor->mOTAUpdateHandle));
    if (err != ESP_OK)
    {
        imageProcessor->mDownloader->OnPreparedForDownload(ESP32Utils::MapError(err));
        return;
    }

#if CONFIG_ENABLE_DELTA_OTA
    esp_delta_ota_cfg_t * deltaOtaCfg = &(imageProcessor->deltaOtaCfg);
    deltaOtaCfg->partitions[0]        = esp_ota_get_running_partition();
    deltaOtaCfg->partitions[1]        = imageProcessor->mOTAUpdatePartition;
    deltaOtaCfg->partitions_num       = sizeof(deltaOtaCfg->partitions) / sizeof(const esp_partition_t *);
    deltaOtaCfg->ota_image_size_limit_size = 0;
    deltaOtaCfg->magic_number          = PATCH_HEADER_MAGIC;
    /* Get SHA256 digest of running firmware */
    esp_partition_addr_to_sha256(deltaOtaCfg->partitions[0], (uint8_t *) & (deltaOtaCfg->sha_digest), SHA256_DIGEST_LENGTH);
    deltaOtaCfg->sha_image_type = ESP_APP_DESC_MAGIC_WORD;
    imageProcessor->mDeltaOTAUpdateHandle = esp_delta_ota_init(deltaOtaCfg);
    if (imageProcessor->mDeltaOTAUpdateHandle == NULL)
    {
        imageProcessor->mDownloader->OnPreparedForDownload(CHIP_ERROR_WRITE_FAILED);
        return;
    }
#endif

#if CONFIG_ENABLE_ENCRYPTED_OTA
    CHIP_ERROR chipError = imageProcessor->DecryptStart();
    if (chipError != CHIP_NO_ERROR)
    {
        ChipLogError(SoftwareUpdate, "Failed to start decryption process, err:%" CHIP_ERROR_FORMAT, chipError.Format());
        imageProcessor->mDownloader->OnPreparedForDownload(chipError);
        return;
    }
#endif // CONFIG_ENABLE_ENCRYPTED_OTA

    imageProcessor->mHeaderParser.Init();
    imageProcessor->mDownloader->OnPreparedForDownload(CHIP_NO_ERROR);
    PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadInProgress);
}
```

