    // Verify the SHA256 digest of the running firmware matches the one in the patch header
    uint16_t patchSize = 0;
    uint8_t baseSha[SHA256_DIGEST_LENGTH] = {0};

    if (block.size() < PATCH_HEADER_LENGTH)
    {
        return CHIP_ERROR_BUFFER_TOO_SMALL;
    }

    // magic check (already done in VerifyChipId, but double check)
    if (block.data()[0] != PATCH_HEADER_MAGIC) { return CHIP_ERROR_INVALID_FILE_IDENTIFIER; }

    // patch size
    memcpy(&patchSize, block.data() + PATCH_SIZE_POSITION, PATCH_SIZE_TYPE_SIZE);
    if (patchSize <= 0 || patchSize > PATCH_SIZE_MASK) { return CHIP_ERROR_INVALID_ARGUMENT; }

    // sha256 digest of running firmware
    memcpy(baseSha, block.data() + SHA256_DIGEST_POSITION, SHA256_DIGEST_LENGTH);
    uint8_t digest[SHA256_DIGEST_LENGTH] = {0};
    esp_err_t err = esp_partition_addr_to_sha256(esp_ota_get_running_partition(), digest, SHA256_DIGEST_LENGTH);
    if (err != ESP_OK) { return ESP32Utils::MapError(err); }
    if (memcmp(digest, baseSha, SHA256_DIGEST_LENGTH) != 0)
    {
        ChipLogError(SoftwareUpdate, "SHA256 digest mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    patchHeaderVerified = true;
    return CHIP_NO_ERROR;
}
