// File-scope state shared by the static delta callbacks (single OTA at a time).
#if CONFIG_ENABLE_DELTA_OTA
static const esp_partition_t * sDeltaOTABasePartition = nullptr;
static uint32_t sDeltaOTABaseReadOffset = 0;
static esp_ota_handle_t sDeltaOTAWriteHandle = 0;
#endif

BC26Result OTAImageProcessorImpl::DeltaOTAReadCallback(void * handle, size_t * size, void * data)
{
    VerifyOrReturn((size != nullptr) && (data != nullptr), BC_ERR_INVALID_ARG);

    if (sDeltaOTABasePartition == nullptr)
    {
        return BC_ERR_INVALID_ARG;
    }

    // Read `*size` bytes of the running (base) firmware image.
    // If fewer bytes remain, `*size` is updated to reflect what was read.
    size_t bytesRead = *size;
    if (sDeltaOTABaseReadOffset >= sDeltaOTABasePartition->size)
    {
        bytesRead = 0;
    }
    else if (bytesRead > (sDeltaOTABasePartition->size - sDeltaOTABaseReadOffset))
    {
        bytesRead = sDeltaOTABasePartition->size - sDeltaOTABaseReadOffset;
    }

    esp_err_t err = esp_partition_read(sDeltaOTABasePartition, sDeltaOTABaseReadOffset, data, bytesRead);
    if (err != ESP_OK)
    {
        return BC_ERR_FLASH_WRITE_FAIL;
    }

    sDeltaOTABaseReadOffset += bytesRead;
    *size = bytesRead;
    return BC26OK;
}

BC26Result OTAImageProcessorImpl::DeltaOTAWriteCallback(void * handle, size_t size, uint8_t * data)
{
    if (size == 0 || data == nullptr)
    {
        return BC_ERR_INVALID_ARG;
    }

    esp_err_t err = esp_ota_write(sDeltaOTAWriteHandle, data, size);
    if (err != ESP_OK)
    {
        return BC_ERR_FLASH_WRITE_FAIL;
    }
    return BC26OK;
}
```

