```cpp
CHIP_ERROR OTAImageProcessorImpl::VerifyChipId(ByteSpan & block)
{
    // Verify that the patch is meant for the chip on which this firmware runs.
    // Patch header layout: magic(1), reserved(3), patch_size(2), chip_id(2), sha256(32)
    if (block.size() < (CHIP_ID_POSITION + CHIP_ID_TYPE_SIZE))
    {
        return CHIP_ERROR_BUFFER_TOO_SMALL;
    }

    if (block.data()[0] != PATCH_HEADER_MAGIC)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch header magic mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    uint16_t chipId = 0;
    memcpy(&chipId, block.data() + CHIP_ID_POSITION, CHIP_ID_TYPE_SIZE);

    esp_chip_info_t chipInfo;
    esp_chip_info(&chipInfo);
    if (static_cast<uint16_t>(chipInfo.model) != chipId)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch chip id mismatch, expected %u, got %u",
                     chipId, static_cast<uint16_t>(chipInfo.model));
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    chipIdVerified = true;
    return CHIP_NO_ERROR;
}
```

VerifyPatchHeader:

```cpp
CHIP_ERROR OTAImageProcessorImpl::VerifyPatchHeader(ByteSpan & block)
{
    if (block.size() < PATCH_HEADER_LENGTH)
    {
        return CHIP_ERROR_BUFFER_TOO_SMALL;
    }

    if (block.data()[0] != PATCH_HEADER_MAGIC)
    {
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    uint16_t patchSize = 0;
    memcpy(&patchSize, block.data() + PATCH_SIZE_POSITION, PATCH_SIZE_TYPE_SIZE);
    if (patchSize == 0 || patchSize > PATCH_SIZE_MASK)
    {
        ChipLogError(SoftwareUpdate, "Invalid delta OTA patch size %d", patchSize);
        return CHIP_ERROR_INVALID_ARGUMENT;
    }

    // SHA256 digest of the firmware that this patch is based on must match
    // the digest of the currently running firmware.
    uint8_t expectedSha[SHA256_DIGEST_LENGTH] = { 0 };
    memcpy(expectedSha, block.data() + SHA256_DIGEST_POSITION, SHA256_DIGEST_LENGTH);

    uint8_t runningSha[SHA256_DIGEST_LENGTH] = { 0 };
    esp_err_t err = esp_partition_get_sha256(esp_ota_get_running_partition(), runningSha);
    if (err != ESP_OK)
    {
        ESP_LOGE(TAG, "Failed to get running firmware SHA256 digest, esp_err:%d", err);
        return ESP32Utils::MapError(err);
    }

    if (memcmp(expectedSha, runningSha, SHA256_DIGEST_LENGTH) != 0)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch SHA256 digest mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    patchHeaderVerified = true;
    return CHIP_NO_ERROR;
}
```

