```cpp
void OTAImageProcessorImpl::HandleProcessBlock(intptr_t context)
{
    auto * imageProcessor = reinterpret_cast<OTAImageProcessorImpl *>(context);
    if (imageProcessor == nullptr)
    {
        ChipLogError(SoftwareUpdate, "ImageProcessor context is null");
        return;
    }
    else if (imageProcessor->mDownloader == nullptr)
    {
        ChipLogError(SoftwareUpdate, "mDownloader is null");
        return;
    }

    ByteSpan block = ByteSpan(imageProcessor->mBlock.data(), imageProcessor->mBlock.size());

    CHIP_ERROR error = imageProcessor->ProcessHeader(block);
    if (error != CHIP_NO_ERROR)
    {
        ESP_LOGE(TAG, "Failed to process OTA image header");
        imageProcessor->mDownloader->EndDownload(error);
        PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadFailed);
        return;
    }

    esp_err_t err;
    ByteSpan blockToWrite = block;

#if CONFIG_ENABLE_ENCRYPTED_OTA
    error = imageProcessor->DecryptBlock(block, blockToWrite);
    if (error != CHIP_NO_ERROR)
    {
        ChipLogError(SoftwareUpdate, "esp_encrypted_img_decrypt_data failed err:%" CHIP_ERROR_FORMAT, error.Format());
        imageProcessor->mDownloader->EndDownload(CHIP_ERROR_WRITE_FAILED);
        PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadFailed);
        return;
    }
#endif // CONFIG_ENABLE_ENCRYPTED_OTA

#if CONFIG_ENABLE_DELTA_OTA
    if (!imageProcessor->patchHeaderVerified)
    {
        error = imageProcessor->VerifyHeaderData(blockToWrite);
        if (error != CHIP_NO_ERROR)
        {
            ESP_LOGE(TAG, "Failed to process delta OTA patch header");
            imageProcessor->mDownloader->EndDownload(error);
            PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadFailed);
            return;
        }
    }

    // Bytes of the current block that are part of the already verified patch
    // header must not be forwarded to the delta OTA library.
    uint16_t headerBytesInBlock = (imageProcessor->patchHeaderVerified && (imageProcessor->bytesReceived < PATCH_HEADER_LENGTH))
        ? static_cast<uint16_t>(PATCH_HEADER_LENGTH - imageProcessor->bytesReceived)
        : 0;
    imageProcessor->bytesReceived += static_cast<uint16_t>(blockToWrite.size());

    if (imageProcessor->patchHeaderVerified)
    {
        ByteSpan deltaBlock(blockToWrite.data() + headerBytesInBlock, blockToWrite.size() - headerBytesInBlock);
        if (!deltaBlock.empty())
        {
            BC26Result result = esp_delta_ota_feed_patch(imageProcessor->mDeltaOTAUpdateHandle,
                                                         const_cast<uint8_t *>(deltaBlock.data()), deltaBlock.size());
            if (result != BC26OK)
            {
                ESP_LOGE(TAG, "esp_delta_ota_feed_patch failed with %d", result);
                imageProcessor->mDownloader->EndDownload(CHIP_ERROR_WRITE_FAILED);
                PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadFailed);
                return;
            }
        }
    }

#if CONFIG_ENABLE_ENCRYPTED_OTA
    free((void *) (blockToWrite.data()));
#endif // CONFIG_ENABLE_ENCRYPTED_OTA

    imageProcessor->mParams.downloadedBytes += blockToWrite.size();
    imageProcessor->mDownloader->FetchNextData();
    return;
#else
    err = esp_ota_write(imageProcessor->mOTAUpdateHandle, blockToWrite.data(), blockToWrite.size());

#if CONFIG_ENABLE_ENCRYPTED_OTA
    free((void *) (blockToWrite.data()));
#endif // CONFIG_ENABLE_ENCRYPTED_OTA

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG, "esp_ota_write failed (%s)", esp_err_to_name(err));
        imageProcessor->mDownloader->EndDownload(CHIP_ERROR_WRITE_FAILED);
        PostOTAStateChangeEvent(DeviceLayer::kOtaDownloadFailed);
        return;
    }

    imageProcessor->mParams.downloadedBytes += blockToWrite.size();
    imageProcessor->mDownloader->FetchNextData();
#endif // CONFIG_ENABLE_DELTA_OTA
