CHIP_ERROR OTAImageProcessorImpl::VerifyChipId(ByteSpan & block)
{
    // Verify that the delta OTA patch is destined for the chip on which this
    // firmware is running. Patch header layout:
    // | magic(1) | reserved(3) | patch_size(2) | chip_id(2) | sha256(32) |
    if (block.size() < (CHIP_ID_POSITION + CHIP_ID_TYPE_SIZE))
    {
        return CHIP_ERROR_BUFFER_TOO_SMALL;
    }

    if (block.data()[0] != PATCH_HEADER_MAGIC)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch header magic mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    uint16_t chipId = 0;
    memcpy(&chipId, block.data() + CHIP_ID_POSITION, CHIP_ID_TYPE_SIZE);

    esp_chip_info_t chipInfo;
    esp_chip_info(&chipInfo);
    if (static_cast<uint16_t>(chipInfo.model) != chipId)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch chip id mismatch, expected %u, got %u", chipId,
                     static_cast<uint16_t>(chipInfo.model));
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    chipIdVerified = true;
    return CHIP_NO_ERROR;
}

CHIP_ERROR OTAImageProcessorImpl::VerifyPatchHeader(ByteSpan & block)
{
    if (block.size() < PATCH_HEADER_LENGTH)
    {
        return CHIP_ERROR_BUFFER_TOO_SMALL;
    }

    if (block.data()[0] != PATCH_HEADER_MAGIC)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch header magic mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    uint16_t patchSize = 0;
    memcpy(&patchSize, block.data() + PATCH_SIZE_POSITION, PATCH_SIZE_TYPE_SIZE);
    if (patchSize == 0 || patchSize > PATCH_SIZE_MASK)
    {
        ChipLogError(SoftwareUpdate, "Invalid delta OTA patch size %u", patchSize);
        return CHIP_ERROR_INVALID_ARGUMENT;
    }

    // The SHA256 digest recorded in the patch header must match the digest of
    // the currently running firmware, since the patch is created against it.
    uint8_t expectedSha[SHA256_DIGEST_LENGTH] = { 0 };
    memcpy(expectedSha, block.data() + SHA256_DIGEST_POSITION, SHA256_DIGEST_LENGTH);

    uint8_t runningSha[SHA256_DIGEST_LENGTH] = { 0 };
    esp_err_t err                            = esp_partition_get_sha256(esp_ota_get_running_partition(), runningSha);
    if (err != ESP_OK)
    {
        ESP_LOGE(TAG, "Failed to get running firmware SHA256 digest, esp_err:%d", err);
        return ESP32Utils::MapError(err);
    }

    if (memcmp(expectedSha, runningSha, SHA256_DIGEST_LENGTH) != 0)
    {
        ChipLogError(SoftwareUpdate, "Delta OTA patch SHA256 digest mismatch");
        return CHIP_ERROR_INVALID_FILE_IDENTIFIER;
    }

    patchHeaderVerified = true;
    return CHIP_NO_ERROR;
}

CHIP_ERROR OTAImageProcessorImpl::VerifyHeaderData(ByteSpan & block)
{
    // The delta OTA patch header (PATCH_HEADER_LENGTH bytes) may span multiple
    // download blocks, so accumulate it before running any verification on it.
    size_t toCopy = block.size();
    if (toCopy > static_cast<size_t>(PATCH_HEADER_LENGTH - patchSizeReceived))
    {
        toCopy = static_cast<size_t>(PATCH_HEADER_LENGTH - patchSizeReceived);
    }

    if (toCopy > 0)
    {
        memcpy(headersReceived + patchSizeReceived, block.data(), toCopy);
        patchSizeReceived += static_cast<uint16_t>(toCopy);
    }

    if (patchSizeReceived < PATCH_HEADER_LENGTH)
    {
        // The complete patch header has not been received yet.
        return CHIP_NO_ERROR;
    }

    ByteSpan header(headersReceived, PATCH_HEADER_LENGTH);

    if (!chipIdVerified)
    {
        ReturnErrorOnFailure(VerifyChipId(header));
    }
    ReturnErrorOnFailure(VerifyPatchHeader(header));

    return CHIP_NO_ERROR;
}

BC26Result OTAImageProcessorImpl::DeltaOTAReadCallback(void * handle, size_t * size, void * data)
{
    (void) handle;

    if (size == nullptr || data == nullptr)
    {
        return BC_ERR_INVALID_ARG;
    }

    if (sDeltaOTABasePartition == nullptr)
    {
        return BC_ERR_INVALID_ARG;
    }

    // Provide the base (currently running) firmware image to the delta OTA
    // library in sequential chunks.
    if (sDeltaOTABaseReadOffset >= sDeltaOTABasePartition->size)
    {
        *size = 0;
        return BC26OK;
    }

    size_t bytesToRead = *size;
    if (bytesToRead > (sDeltaOTABasePartition->size - sDeltaOTABaseReadOffset))
    {
        bytesToRead = sDeltaOTABasePartition->size - sDeltaOTABaseReadOffset;
    }

    esp_err_t err = esp_partition_read(sDeltaOTABasePartition, sDeltaOTABaseReadOffset, data, bytesToRead);
    if (err != ESP_OK)
    {
        ESP_LOGE(TAG, "esp_partition_read failed (%s)", esp_err_to_name(err));
        return BC_ERR_FLASH_WRITE_FAIL;
    }

    sDeltaOTABaseReadOffset += bytesToRead;
    *size = bytesToRead;
    return BC26OK;
}

BC26Result OTAImageProcessorImpl::DeltaOTAWriteCallback(void * handle, size_t size, uint8_t * data)
{
    (void) handle;

    if (size == 0 || data == nullptr)
    {
        return BC_ERR_INVALID_ARG;
    }

    // Persist the decompressed image produced by the delta OTA library.
    esp_err_t err = esp_ota_write(sDeltaOTAWriteHandle, data, size);
    if (err != ESP_OK)
    {
        ESP_LOGE(TAG, "esp_ota_write failed (%s)", esp_err_to_name(err));
        return BC_ERR_FLASH_WRITE_FAIL;
    }

    return BC26OK;
}
