def strip(txt):
    txt = re.sub(r'//[^\n]*','',txt)
    txt = re.sub(r'/\*.*?\*/','',txt,flags=re.S)
    return txt

def extract(text, name, limit=200000):
    out=[]; i=0; steps=0
    pat=re.compile(r'\b'+re.escape(name)+r'\(')
    while steps<limit:
        steps+=1
        m=pat.search(text,i)
        if not m: break
        start=m.end(); depth=0; j=start; last=start
        while True:
            if j>=len(text):
                print("UNCLOSED at",name,j); return None
            c=text[j]
            if c=='(': depth+=1
            elif c==')':
                depth-=1
                if depth==0:
                    out.append(text[last:j]); i=j+1; break
            elif c=='{':
                d=1; j+=1
                while d>0 and j<len(text):
                    if text[j]=='{': d+=1
                    elif text[j]=='}': d-=1
                    if d==0: break
                    j+=1
            elif c=='"':
                j+=1
                while j<len(text):
                    if text[j]=='\\': j+=2; continue
                    if text[j]=='"': break
                    j+=1
            j+=1
    return out

