  deps = [ "${chip_root}/src/platform/logging:headers" ]

  config("siwx917-psa-crypto-config") {
    if (use_siwx917_psa_crypto && chip_crypto == "platform") {
      # The PSA crypto implementation uses mbedTLS private headers that live
      # in the mbedTLS library directory.
      include_dirs = [ "${chip_root}/third_party/mbedtls/repo/library" ]
    }
  }
  public_configs += [ ":siwx917-psa-crypto-config" ]

  # Add platform crypto implementation
  if (chip_crypto == "platform") {
    if (use_siwx917_psa_crypto) {
      sources += [ "CHIPCryptoPALPSASiWx917.cpp" ]
    } else {
      sources += [ "CHIPCryptoPALTinyCrypt.cpp" ]
    }
    public_deps += [
      "${chip_root}/src/crypto",
      "${mbedtls_root}:mbedtls",
    ]
  }

arguments.newString:
"wifi/wifi_config.h",
  ]
  public_configs += [ ":siwx917-platform-wifi-config" ]
}

